var datum, txt;

// Beschreibe diese Funktion …
async function Logfile(datum, txt) {
    if (getState('0_userdata.0.go-e_V4.DebugAktiv_V4').val) {
      require('fs').appendFileSync('/opt/iobroker/log/' + datum + ' - go_E_V4.log', formatDate(new Date(), "hh:mm:ss") + " \t" + txt + "\n");}
}


// ------->>>> Logfile

// ------->>>> LIMITS
// minAmpere
setState('go-e.1.ampere' /* Ampere for PWM (amp) */, parseFloat(getState('0_userdata.0.go-e_V4.minA_1P_V4').val), true);
on({ id: [].concat(['go-e.1.ampere']).concat(['0_userdata.0.go-e_V4.maxA_1P_V4']).concat(['0_userdata.0.go-e_V4.maxA_3P_V4']).concat(['0_userdata.0.go-e_V4.minA_1P_V4']).concat(['0_userdata.0.go-e_V4.minA_3P_V4']), change: 'ne' }, async (obj) => {
  if (getState('0_userdata.0.go-e_V4.3P_V4').val) {
    if (getState('go-e.1.ampere').val < getState('0_userdata.0.go-e_V4.minA_3P_V4').val) {
      setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e_V4.minA_3P_V4').val), true);
    }
  } else {
    if (getState('go-e.1.ampere').val < getState('0_userdata.0.go-e_V4.minA_1P_V4').val) {
      setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e_V4.minA_1P_V4').val), true);
    }
  }
  if (getState('go-e.1.ampere').val > getState('go-e.1.max_ampere').val) {
    setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('go-e.1.max_ampere').val), true);
  }
  if (getState('go-e.1.ampere').val > getState('0_userdata.0.go-e_V4.maxA_1P_V4').val && getState('0_userdata.0.go-e_V4.1P_V4').val) {
    setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e_V4.maxA_1P_V4').val), true);
  }
  if (getState('go-e.1.ampere').val > getState('0_userdata.0.go-e_V4.maxA_3P_V4').val && getState('0_userdata.0.go-e_V4.3P_V4').val) {
    setState('go-e.1.amperePV' /* Ampere for PWM (amx) (FW > 033 required) */, parseFloat(getState('0_userdata.0.go-e_V4.maxA_3P_V4').val), true);
  }
});
// maxAmpere
on({ id: [].concat(['0_userdata.0.go-e_V4.minA_1P_V4']).concat(['0_userdata.0.go-e_V4.maxA_1P_V4']), change: 'ne' }, async (obj) => {
  if (getState('0_userdata.0.go-e_V4.minA_1P_V4').val > getState('0_userdata.0.go-e_V4.maxA_1P_V4').val) {
    setState('0_userdata.0.go-e_V4.maxA_1P_V4' /* maxAmpere_1P_V4 */, getState('0_userdata.0.go-e_V4.minA_1P_V4').val);
  }
});
on({ id: [].concat(['0_userdata.0.go-e_V4.minA_3P_V4']).concat(['0_userdata.0.go-e_V4.maxA_3P_V4']), change: 'ne' }, async (obj) => {
  if (getState('0_userdata.0.go-e_V4.minA_3P_V4').val > getState('0_userdata.0.go-e_V4.maxA_3P_V4').val) {
    setState('0_userdata.0.go-e_V4.maxA_3P_V4' /* maxAmpere_3P_V4 */, getState('0_userdata.0.go-e_V4.minA_3P_V4').val);
  }
});


